{"filePath": "/app/server.js", "content": "const path = require('path');
const fastify = require('fastify')({ logger: false });

const PORT = Number(process.env.APPLICATION_PORT || 8000);
const connectionString = process.env.POSTGRES_DATABASE_URL;

if (!connectionString) {
  throw new Error('POSTGRES_DATABASE_URL is required');
}

fastify.register(require('@fastify/postgres'), { connectionString });
fastify.register(require('fastify-static'), {
  root: path.join(__dirname, 'public'),
  prefix: '/',
});

async function initializeDatabase() {
  await fastify.pg.query(`
    CREATE TABLE IF NOT EXISTS notes (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      body TEXT NOT NULL DEFAULT '',
      updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    )
  `);
}

fastify.get('/api/notes', async () => {
  const result = await fastify.pg.query('SELECT id, body, updated_at FROM notes ORDER BY updated_at DESC');
  return result.rows;
});

fastify.post('/api/notes', async () => {
  const result = await fastify.pg.query(
    "INSERT INTO notes (body, updated_at) VALUES ('', NOW()) RETURNING id, body, updated_at"
  );
  return result.rows[0];
});

fastify.put('/api/notes/:id', async (request, reply) => {
  const body = typeof request.body?.body === 'string' ? request.body.body : '';
  const result = await fastify.pg.query(
    'UPDATE notes SET body = $1, updated_at = NOW() WHERE id = $2 RETURNING id, body, updated_at',
    [body, request.params.id]
  );
  if (!result.rowCount) {
    return reply.code(404).send({ error: 'Note not found' });
  }
  return result.rows[0];
});

fastify.delete('/api/notes/:id', async (request, reply) => {
  const result = await fastify.pg.query('DELETE FROM notes WHERE id = $1', [request.params.id]);
  if (!result.rowCount) {
    return reply.code(404).send({ error: 'Note not found' });
  }
  return { ok: true };
});

fastify.setNotFoundHandler((request, reply) => {
  if (request.raw.url.startsWith('/api/')) {
    return reply.code(404).send({ error: 'Not found' });
  }
  return reply.sendFile('index.html');
});

async function start() {
  await initializeDatabase();
  await fastify.listen({ port: PORT, host: '0.0.0.0' });
}

start().catch((error) => {
  console.error(error);
  process.exit(1);
});
"}

{"filePath": "/app/public/app.js", "content": "const PASSWORD = 'my-notes-are-mine';
const app = document.querySelector('#app');
let unlocked = false;
let notes = [];
let currentNoteId = null;
let currentText = '';
let dirty = false;

function escapeHtml(value) {
  return value.replace(/[&<>"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[char]);
}

function formatTime(value) {
  const date = new Date(value);
  const pad = (number) => String(number).padStart(2, '0');
  return `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())} ${pad(date.getUTCHours())}:${pad(date.getUTCMinutes())}`;
}

function noteTitle(note) {
  const line = note.body.split('\n').find((item) => item.trim());
  return line ? line.trim() : 'New Note';
}

function notePreview(note) {
  const lines = note.body.split('\n');
  const titleIndex = lines.findIndex((item) => item.trim());
  const preview = lines.slice(titleIndex + 1).join(' ').trim();
  return preview || 'No additional text';
}

function navigate(path) {
  history.pushState({}, '', path);
  route();
}

async function loadNotes() {
  const response = await fetch('/api/notes');
  notes = await response.json();
}

async function saveCurrent() {
  if (!dirty || !currentNoteId) return;
  const response = await fetch(`/api/notes/${currentNoteId}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ body: currentText }),
  });
  if (response.ok) {
    const updated = await response.json();
    notes = notes.map((note) => (note.id === updated.id ? updated : note));
    dirty = false;
  }
}

function renderGate(message = '') {
  app.innerHTML = `
    <section class="gate" data-testid="section-password-gate">
      <div class="gate-card" data-testid="card-password-gate">
        <p class="eyebrow" data-testid="text-app-label">Private Notes</p>
        <h1 data-testid="text-gate-title">Unlock your notes</h1>
        <p class="muted" data-testid="text-gate-description">Enter the password to access this tab session.</p>
        <form id="gate-form" class="gate-form" data-testid="form-unlock">
          <label data-testid="label-password">Password</label>
          <input id="password" type="password" autocomplete="current-password" data-testid="input-password" />
          <p class="error ${message ? '' : 'hidden'}" data-testid="text-password-error">${escapeHtml(message)}</p>
          <button type="submit" data-testid="button-unlock">Unlock</button>
        </form>
      </div>
    </section>
  `;
  document.querySelector('#password').focus();
  document.querySelector('#gate-form').addEventListener('submit', async (event) => {
    event.preventDefault();
    const password = document.querySelector('#password').value;
    if (!password) return renderGate('Password is required');
    if (password !== PASSWORD) return renderGate('Incorrect password');
    unlocked = true;
    await loadNotes();
    route();
  });
}

function listTemplate(filtered, query) {
  const rows = filtered.map((note) => `
    <article class="note-row" data-testid="card-note-${note.id}" data-id="${note.id}" tabindex="0">
      <div>
        <h2 data-testid="text-title-${note.id}">${escapeHtml(noteTitle(note))}</h2>
        <p data-testid="text-preview-${note.id}">${escapeHtml(notePreview(note))}</p>
      </div>
      <div class="row-actions">
        <time data-testid="text-timestamp-${note.id}">${formatTime(note.updated_at)}</time>
        <button class="ghost danger delete-list" data-testid="button-delete-${note.id}" data-id="${note.id}">Delete</button>
      </div>
    </article>
  `).join('');
  return `
    <section class="shell" data-testid="section-notes-list">
      <header class="topbar" data-testid="header-notes">
        <div>
          <p class="eyebrow" data-testid="text-app-label">Private Notes</p>
          <h1 data-testid="text-list-title">All Notes</h1>
        </div>
        <button id="new-note" data-testid="button-new-note">New Note</button>
      </header>
      <label class="search-label" data-testid="label-search">Search notes</label>
      <input id="search" class="search" value="${escapeHtml(query)}" placeholder="Search by title or body" data-testid="input-search" />
      <div class="meta" data-testid="text-note-count">${filtered.length} note${filtered.length === 1 ? '' : 's'}</div>
      <div class="notes" data-testid="list-notes">
        ${rows || '<div class="empty" data-testid="text-empty-state">No notes yet. Create your first note.</div>'}
      </div>
    </section>
  `;
}

function renderList() {
  currentNoteId = null;
  currentText = '';
  dirty = false;
  const params = new URLSearchParams(location.search);
  const query = params.get('q') || '';
  const normalized = query.toLowerCase();
  const filtered = notes.filter((note) => !normalized || noteTitle(note).toLowerCase().includes(normalized) || note.body.toLowerCase().includes(normalized));
  app.innerHTML = listTemplate(filtered, query);
  document.querySelector('#new-note').addEventListener('click', async () => {
    const response = await fetch('/api/notes', { method: 'POST' });
    const note = await response.json();
    notes.unshift(note);
    navigate(`/notes/${note.id}`);
  });
  document.querySelector('#search').addEventListener('input', (event) => {
    const value = event.target.value;
    history.replaceState({}, '', value ? `/?q=${encodeURIComponent(value)}` : '/');
    renderList();
    document.querySelector('#search').focus();
  });
  document.querySelectorAll('.note-row').forEach((row) => {
    row.addEventListener('click', () => navigate(`/notes/${row.dataset.id}`));
    row.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') navigate(`/notes/${row.dataset.id}`);
    });
  });
  document.querySelectorAll('.delete-list').forEach((button) => {
    button.addEventListener('click', async (event) => {
      event.stopPropagation();
      await deleteNote(button.dataset.id, false);
    });
  });
}

async function deleteNote(id, fromEditor) {
  if (!confirm('Permanently delete this note? This action cannot be undone.')) return;
  const response = await fetch(`/api/notes/${id}`, { method: 'DELETE' });
  if (response.ok) {
    notes = notes.filter((note) => note.id !== id);
    if (fromEditor) navigate('/');
    else renderList();
  }
}

function renderEditor(id) {
  const note = notes.find((item) => item.id === id);
  if (!note) return navigate('/');
  currentNoteId = id;
  currentText = note.body;
  dirty = false;
  app.innerHTML = `
    <section class="shell editor-shell" data-testid="section-note-editor">
      <header class="topbar" data-testid="header-editor">
        <button id="back" class="ghost" data-testid="button-back-list">Back to notes</button>
        <div class="editor-actions">
          <time data-testid="text-editor-timestamp">Last edited ${formatTime(note.updated_at)}</time>
          <button id="delete-editor" class="ghost danger" data-testid="button-delete-note">Delete</button>
        </div>
      </header>
      <textarea id="body" data-testid="input-note-body" placeholder="Start typing...">${escapeHtml(note.body)}</textarea>
    </section>
  `;
  const textarea = document.querySelector('#body');
  textarea.focus();
  textarea.addEventListener('input', () => {
    currentText = textarea.value;
    dirty = true;
  });
  document.querySelector('#back').addEventListener('click', async () => {
    await saveCurrent();
    await loadNotes();
    navigate('/');
  });
  document.querySelector('#delete-editor').addEventListener('click', () => deleteNote(id, true));
}

async function route() {
  if (!unlocked) return renderGate();
  const match = location.pathname.match(/^\/notes\/([^/]+)$/);
  if (match) return renderEditor(match[1]);
  return renderList();
}

window.addEventListener('popstate', async () => {
  await saveCurrent();
  await loadNotes();
  route();
});

window.addEventListener('beforeunload', () => {
  if (dirty && currentNoteId) {
    navigator.sendBeacon(`/api/notes/${currentNoteId}`, new Blob([JSON.stringify({ body: currentText })], { type: 'application/json' }));
  }
});

route();
"}

{"filePath": "/app/public/styles.css", "content": ":root {
  color-scheme: light;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #f5f0e8;
  color: #231f20;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background: radial-gradient(circle at 15% 10%, #ffe2b8 0, transparent 30%), radial-gradient(circle at 90% 0, #d7e8ff 0, transparent 32%), #f8f4ee;
}

button, input, textarea {
  font: inherit;
}

button {
  border: 0;
  border-radius: 999px;
  background: #111827;
  color: white;
  padding: 0.85rem 1.2rem;
  cursor: pointer;
  font-weight: 800;
  box-shadow: 0 12px 30px rgba(17, 24, 39, 0.18);
}

button:hover {
  transform: translateY(-1px);
}

.ghost {
  background: rgba(255, 255, 255, 0.75);
  color: #111827;
  border: 1px solid rgba(17, 24, 39, 0.12);
  box-shadow: none;
}

.danger {
  color: #b42318;
}

.gate {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 1.5rem;
}

.gate-card, .shell {
  width: min(920px, calc(100vw - 2rem));
  border: 1px solid rgba(255, 255, 255, 0.7);
  background: rgba(255, 255, 255, 0.72);
  backdrop-filter: blur(18px);
  border-radius: 32px;
  box-shadow: 0 30px 80px rgba(31, 41, 55, 0.14);
}

.gate-card {
  max-width: 460px;
  padding: 2rem;
}

.eyebrow {
  margin: 0 0 0.5rem;
  color: #c2410c;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.78rem;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0.5rem;
  font-size: clamp(2rem, 5vw, 3.8rem);
  letter-spacing: -0.06em;
}

h2 {
  margin-bottom: 0.25rem;
  font-size: 1.1rem;
}

.muted, .note-row p, .meta, time {
  color: #6b7280;
}

.gate-form {
  display: grid;
  gap: 0.85rem;
  margin-top: 1.5rem;
}

label {
  font-weight: 800;
}

input, textarea {
  width: 100%;
  border: 1px solid rgba(17, 24, 39, 0.12);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.82);
  padding: 1rem;
  outline: none;
}

input:focus, textarea:focus {
  border-color: #f97316;
  box-shadow: 0 0 0 4px rgba(249, 115, 22, 0.14);
}

.error {
  color: #b42318;
  margin: 0;
  font-weight: 700;
}

.hidden {
  display: none;
}

.shell {
  margin: 3rem auto;
  padding: 1.25rem;
}

.topbar {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
  margin-bottom: 1.25rem;
}

.search-label {
  display: block;
  margin-bottom: 0.5rem;
}

.search {
  margin-bottom: 0.9rem;
}

.meta {
  margin-bottom: 0.9rem;
  font-weight: 700;
}

.notes {
  display: grid;
  gap: 0.75rem;
}

.note-row {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
  padding: 1rem;
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(17, 24, 39, 0.08);
  cursor: pointer;
}

.note-row:hover, .note-row:focus {
  background: white;
  outline: none;
  transform: translateY(-1px);
}

.note-row p {
  margin: 0;
  max-width: 52ch;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.row-actions, .editor-actions {
  display: flex;
  gap: 0.8rem;
  align-items: center;
  flex-shrink: 0;
}

.empty {
  padding: 3rem 1rem;
  text-align: center;
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.55);
  color: #6b7280;
  font-weight: 800;
}

.editor-shell {
  min-height: calc(100vh - 6rem);
  display: flex;
  flex-direction: column;
}

textarea {
  flex: 1;
  min-height: 65vh;
  resize: none;
  border-radius: 26px;
  line-height: 1.7;
  font-size: 1.08rem;
}

@media (max-width: 720px) {
  .topbar, .note-row, .row-actions, .editor-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .shell {
    margin: 1rem auto;
  }
}
"}

