{"filePath": "/app/server.js", "content": "const express = require('express');
const path = require('path');
const { Pool } = require('pg');

const app = express();
const port = process.env.APPLICATION_PORT || 8000;
const pool = new Pool({ connectionString: process.env.POSTGRES_DATABASE_URL });
const barbers = ['Alex', 'Lucy', 'George'];

app.disable('x-powered-by');
app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

function validDate(value) {
  return /^\d{4}-\d{2}-\d{2}$/.test(value || '');
}

function validTime(value) {
  if (!/^\d{2}:\d{2}$/.test(value || '')) return false;
  const [hour, minute] = value.split(':').map(Number);
  return hour >= 9 && hour < 18 && (minute === 0 || minute === 30);
}

function endTime(value) {
  const [hour, minute] = value.split(':').map(Number);
  const date = new Date(Date.UTC(2000, 0, 1, hour, minute + 30));
  return date.toISOString().slice(11, 16);
}

function validateSlot({ date, start_time, barber }) {
  if (!validDate(date)) return 'Choose a valid date.';
  if (!validTime(start_time)) return 'Choose a valid time between 09:00 and 17:30.';
  if (!barbers.includes(barber)) return 'Choose a valid barber.';
  return null;
}

app.get('/api/config', (req, res) => {
  res.json({ timezone: 'UTC', hours: { start: '09:00', end: '18:00' }, slotDuration: 30, barbers });
});

app.get('/api/appointments', async (req, res) => {
  const date = req.query.date;
  if (!validDate(date)) return res.status(400).json({ error: 'Choose a valid date.' });
  const result = await pool.query(
    'SELECT id, appointment_date AS date, to_char(start_time, $2) AS start_time, barber, customer_name, notes, created_at, updated_at FROM appointments WHERE appointment_date = $1 ORDER BY start_time, barber',
    [date, 'HH24:MI']
  );
  res.json(result.rows.map((row) => ({ ...row, end_time: endTime(row.start_time) })));
});

app.post('/api/appointments', async (req, res) => {
  const { date, start_time, barber, customer_name, notes } = req.body;
  const slotError = validateSlot({ date, start_time, barber });
  if (slotError) return res.status(400).json({ error: slotError });
  if (!customer_name || !customer_name.trim()) return res.status(400).json({ error: 'Customer name is required.' });
  try {
    const result = await pool.query(
      'INSERT INTO appointments (appointment_date, start_time, barber, customer_name, notes) VALUES ($1, $2, $3, $4, $5) RETURNING id, appointment_date AS date, to_char(start_time, $6) AS start_time, barber, customer_name, notes, created_at, updated_at',
      [date, start_time, barber, customer_name.trim(), notes || '', 'HH24:MI']
    );
    const appointment = result.rows[0];
    res.status(201).json({ ...appointment, end_time: endTime(appointment.start_time) });
  } catch (error) {
    if (error.code === '23505') return res.status(409).json({ error: 'That slot was just booked. Choose another available slot.' });
    throw error;
  }
});

app.put('/api/appointments/:id', async (req, res) => {
  const { customer_name, notes } = req.body;
  if (!customer_name || !customer_name.trim()) return res.status(400).json({ error: 'Customer name is required.' });
  const result = await pool.query(
    'UPDATE appointments SET customer_name = $1, notes = $2, updated_at = now() WHERE id = $3 RETURNING id, appointment_date AS date, to_char(start_time, $4) AS start_time, barber, customer_name, notes, created_at, updated_at',
    [customer_name.trim(), notes || '', req.params.id, 'HH24:MI']
  );
  if (!result.rowCount) return res.status(404).json({ error: 'Appointment not found.' });
  const appointment = result.rows[0];
  res.json({ ...appointment, end_time: endTime(appointment.start_time) });
});

app.delete('/api/appointments/:id', async (req, res) => {
  const result = await pool.query('DELETE FROM appointments WHERE id = $1', [req.params.id]);
  if (!result.rowCount) return res.status(404).json({ error: 'Appointment not found.' });
  res.status(204).end();
});

app.use((error, req, res, next) => {
  console.error(error);
  res.status(500).json({ error: 'Something went wrong.' });
});

app.listen(port, '0.0.0.0', () => {
  console.log(`Barber scheduler listening on ${port}`);
});
"}

{"filePath": "/app/scripts/setup-db.js", "content": "const { Pool } = require('pg');

async function main() {
  const pool = new Pool({ connectionString: process.env.POSTGRES_DATABASE_URL });
  await pool.query(`
    CREATE TABLE IF NOT EXISTS appointments (
      id SERIAL PRIMARY KEY,
      appointment_date DATE NOT NULL,
      start_time TIME NOT NULL,
      barber TEXT NOT NULL CHECK (barber IN ('Alex', 'Lucy', 'George')),
      customer_name TEXT NOT NULL CHECK (length(trim(customer_name)) > 0),
      notes TEXT NOT NULL DEFAULT '',
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      UNIQUE (appointment_date, start_time, barber)
    )
  `);
  await pool.query(`
    CREATE INDEX IF NOT EXISTS appointments_date_idx
    ON appointments (appointment_date, start_time, barber)
  `);
  await pool.end();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
"}

