}
h1 { font-size: clamp(2.2rem, 5vw, 4.6rem); line-height: 0.95; margin: 8px 0 14px; letter-spacing: -0.06em; }
p { margin: 0; }
.hero p:not(.eyebrow) { color: var(--muted); font-size: 1.05rem; max-width: 650px; }
.eyebrow { color: var(--accent); font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; font-size: 0.75rem; }
.date-card {
  min-width: 260px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 24px;
  background: var(--card);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-self: center;
}
.date-card span { color: var(--muted); font-weight: 700; }
input, textarea {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 12px 14px;
  background: #fffdfb;
  color: var(--ink);
  outline: none;
}
input:focus, textarea:focus { border-color: var(--accent); box-shadow: 0 0 0 4px rgba(155, 91, 53, 0.14); }
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin: 20px 0 14px;
  color: var(--muted);
  font-weight: 700;
}
.legend { display: flex; gap: 16px; flex-wrap: wrap; }
.legend span { display: inline-flex; align-items: center; gap: 8px; }
.legend i { width: 10px; height: 10px; border-radius: 999px; display: inline-block; }
.available-dot { background: var(--green); }
.booked-dot { background: var(--accent); }
.schedule-card { background: var(--card); border: 1px solid var(--line); border-radius: 28px; overflow: hidden; box-shadow: var(--shadow); }
.schedule-grid { display: grid; grid-template-columns: 92px repeat(3, minmax(180px, 1fr)); overflow-x: auto; }
.grid-cell { min-height: 66px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); padding: 10px; }
.header-cell { position: sticky; top: 0; background: #39251b; color: #fff7ef; font-weight: 900; display: flex; align-items: center; justify-content: center; z-index: 1; }
.time-cell { color: var(--muted); font-weight: 900; background: rgba(255, 255, 255, 0.45); display: flex; align-items: center; justify-content: center; }
.slot-button {
  width: 100%;
  min-height: 46px;
  border: 1px dashed #d8c7ba;
