{"filePath": "/app/public/app.js", "content": "const barbers = ['Alex', 'Lucy', 'George'];
const slots = [];
for (let hour = 9; hour < 18; hour += 1) {
  slots.push(`${String(hour).padStart(2, '0')}:00`);
  slots.push(`${String(hour).padStart(2, '0')}:30`);
}

const dateInput = document.querySelector('#schedule-date');
const currentDate = document.querySelector('#current-date');
const grid = document.querySelector('#schedule-grid');
const modal = document.querySelector('#modal');
const modalMode = document.querySelector('#modal-mode');
const modalTitle = document.querySelector('#modal-title');
const meta = document.querySelector('#appointment-meta');
const form = document.querySelector('#appointment-form');
const customerName = document.querySelector('#customer-name');
const notes = document.querySelector('#notes');
const errorBox = document.querySelector('#form-error');
const closeModal = document.querySelector('#close-modal');
const cancelButton = document.querySelector('#cancel-appointment');
let appointments = [];
let selected = null;

function todayUtc() {
  return new Date().toISOString().slice(0, 10);
}

function formatDate(date) {
  return new Intl.DateTimeFormat('en', { timeZone: 'UTC', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }).format(new Date(`${date}T00:00:00Z`));
}

function endTime(start) {
  const [hour, minute] = start.split(':').map(Number);
  const date = new Date(Date.UTC(2000, 0, 1, hour, minute + 30));
  return date.toISOString().slice(11, 16);
}

function testSafe(value) {
  return String(value).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

function appointmentFor(time, barber) {
  return appointments.find((appointment) => appointment.start_time === time && appointment.barber === barber);
}

function element(tag, className, text, testId) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  if (testId) node.dataset.testid = testId;
  return node;
}

function renderMeta(items) {
  meta.innerHTML = '';
  items.forEach(([label, value, id]) => {
    const box = element('div', 'meta-item', undefined, `card-meta-${id}`);
    box.append(element('span', '', label, `text-meta-label-${id}`));
    box.append(element('strong', '', value, `text-meta-value-${id}`));
    meta.append(box);
  });
}

function renderGrid() {
  currentDate.textContent = formatDate(dateInput.value);
  currentDate.dataset.testid = 'text-current-date';
  grid.innerHTML = '';
  grid.append(element('div', 'grid-cell header-cell', 'Time', 'text-header-time'));
  barbers.forEach((barber) => grid.append(element('div', 'grid-cell header-cell', barber, `text-header-${testSafe(barber)}`)));
  slots.forEach((time) => {
    grid.append(element('div', 'grid-cell time-cell', time, `text-time-${testSafe(time)}`));
    barbers.forEach((barber) => {
      const cell = element('div', 'grid-cell', undefined, `cell-${testSafe(barber)}-${testSafe(time)}`);
      const appointment = appointmentFor(time, barber);
      if (appointment) {
        const button = element('button', 'appointment-button', appointment.customer_name, `button-appointment-${appointment.id}`);
        button.type = 'button';
        button.title = `${appointment.customer_name} with ${barber} at ${time}`;
        button.addEventListener('click', () => openExisting(appointment));
        cell.append(button);
      } else {
        const button = element('button', 'slot-button', 'Available', `button-book-${testSafe(barber)}-${testSafe(time)}`);
        button.type = 'button';
        button.addEventListener('click', () => openNew(time, barber));
        cell.append(button);
      }
      grid.append(cell);
    });
  });
}

async function loadAppointments() {
  const response = await fetch(`/api/appointments?date=${encodeURIComponent(dateInput.value)}`);
  appointments = await response.json();
  renderGrid();
}

function openNew(time, barber) {
  selected = { mode: 'new', date: dateInput.value, start_time: time, end_time: endTime(time), barber };
  modalMode.textContent = 'New appointment';
  modalTitle.textContent = 'Book available slot';
  customerName.value = '';
  notes.value = '';
  errorBox.textContent = '';
  cancelButton.classList.add('hidden');
  renderMeta([
    ['Date', formatDate(selected.date), 'date'],
    ['Time', `${selected.start_time}-${selected.end_time}`, 'time'],
    ['Barber', selected.barber, 'barber']
  ]);
  modal.classList.remove('hidden');
  customerName.focus();
}

function openExisting(appointment) {
  selected = { mode: 'edit', ...appointment };
  modalMode.textContent = 'Appointment details';
  modalTitle.textContent = appointment.customer_name;
  customerName.value = appointment.customer_name;
  notes.value = appointment.notes || '';
  errorBox.textContent = '';
  cancelButton.classList.remove('hidden');
  renderMeta([
    ['Date', formatDate(appointment.date), 'date'],
    ['Start', appointment.start_time, 'start-time'],
    ['End', appointment.end_time, 'end-time'],
    ['Barber', appointment.barber, 'barber']
  ]);
  modal.classList.remove('hidden');
  customerName.focus();
}

function hideModal() {
  modal.classList.add('hidden');
  selected = null;
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (!customerName.value.trim()) {
    errorBox.textContent = 'Customer name is required.';
    return;
  }
  const payload = { customer_name: customerName.value.trim(), notes: notes.value };
  const response = await fetch(selected.mode === 'new' ? '/api/appointments' : `/api/appointments/${selected.id}`, {
    method: selected.mode === 'new' ? 'POST' : 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(selected.mode === 'new' ? { ...selected, ...payload } : payload)
  });
  if (!response.ok) {
    const body = await response.json();
    errorBox.textContent = body.error || 'Unable to save appointment.';
    await loadAppointments();
    return;
  }
  hideModal();
  await loadAppointments();
});

cancelButton.addEventListener('click', async () => {
  if (!selected || !confirm('Cancel this appointment?')) return;
  const response = await fetch(`/api/appointments/${selected.id}`, { method: 'DELETE' });
  if (!response.ok) {
    const body = await response.json();
    errorBox.textContent = body.error || 'Unable to cancel appointment.';
    return;
  }
  hideModal();
  await loadAppointments();
});

closeModal.addEventListener('click', hideModal);
modal.addEventListener('click', (event) => {
  if (event.target === modal) hideModal();
});
dateInput.addEventListener('change', loadAppointments);

dateInput.value = todayUtc();
loadAppointments();
"}

