{"filePath": "/app/server.js", "content": "import http from 'node:http';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { Pool } from 'pg';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const port = Number(process.env.APPLICATION_PORT || 8000);
const pool = new Pool({ connectionString: process.env.POSTGRES_DATABASE_URL });

const sendJson = (res, status, data) => {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
};

const sendFile = async (res, filePath, contentType) => {
  try {
    const data = await readFile(filePath);
    res.writeHead(200, { 'content-type': contentType });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('Not found');
  }
};

const shuffle = (items) => [...items].sort(() => Math.random() - 0.5);

const routes = {
  '/api/categories': async (_req, res) => {
    const result = await pool.query('select category, count(*)::int as count from questions group by category order by category');
    sendJson(res, 200, result.rows);
  },
  '/api/quiz': async (req, res) => {
    const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    let category = url.searchParams.get('category') || '';
    let surprise = false;

    if (category === 'Surprise Me!') {
      const categories = await pool.query('select distinct category from questions');
      if (!categories.rows.length) return sendJson(res, 404, { error: 'No questions available' });
      category = shuffle(categories.rows)[0].category;
      surprise = true;
    }

    const result = await pool.query(
      'select id, question, option_a, option_b, option_c, option_d, correct_option, explanation, category from questions where category = $1 order by random() limit 10',
      [category]
    );

    if (!result.rows.length) return sendJson(res, 404, { error: 'Category not found' });
    sendJson(res, 200, { category, surprise, warning: result.rows.length < 10, questions: result.rows });
  }
};

const server = http.createServer(async (req, res) => {
  try {
    const pathname = new URL(req.url, `http://${req.headers.host || 'localhost'}`).pathname;
    if (req.method === 'GET' && routes[pathname]) return routes[pathname](req, res);
    if (req.method === 'GET' && pathname === '/') return sendFile(res, path.join(__dirname, 'public', 'index.html'), 'text/html; charset=utf-8');
    if (req.method === 'GET' && pathname === '/app.js') return sendFile(res, path.join(__dirname, 'public', 'app.js'), 'text/javascript; charset=utf-8');
    if (req.method === 'GET' && pathname === '/styles.css') return sendFile(res, path.join(__dirname, 'public', 'styles.css'), 'text/css; charset=utf-8');
    res.writeHead(404);
    res.end('Not found');
  } catch (error) {
    sendJson(res, 500, { error: error.message });
  }
});

server.listen(port, '0.0.0.0', () => {
  console.log(`Quiz app listening on ${port}`);
});
"}

