import { Pool } from 'pg';

const pool = new Pool({ connectionString: process.env.POSTGRES_DATABASE_URL });

const parseCsv = (text) => {
  const rows = [];
  let row = [];
  let cell = '';
  let quoted = false;

  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    const next = text[i + 1];

    if (char === '"' && quoted && next === '"') {
      cell += '"';
      i += 1;
    } else if (char === '"') {
      quoted = !quoted;
    } else if (char === ',' && !quoted) {
      row.push(cell);
      cell = '';
    } else if ((char === '\n' || char === '\r') && !quoted) {
      if (char === '\r' && next === '\n') i += 1;
      row.push(cell);
      if (row.some((value) => value.length)) rows.push(row);
      row = [];
      cell = '';
    } else {
      cell += char;
    }
  }

  if (cell.length || row.length) {
    row.push(cell);
    rows.push(row);
  }

  const headers = rows.shift();
  return rows.map((values) => Object.fromEntries(headers.map((header, index) => [header, values[index] || ''])));
};

const main = async () => {
  await pool.query(`
    create table if not exists questions (
      id text primary key,
      question text not null,
      option_a text not null,
      option_b text not null,
      option_c text not null,
      option_d text not null,
      correct_option text not null check (correct_option in ('A', 'B', 'C', 'D')),
      explanation text not null,
      category text not null
    )
  `);

  const rows = parseCsv(await readFile('assets/questions.csv', 'utf8'));
  for (const row of rows) {
    await pool.query(
      `insert into questions (id, question, option_a, option_b, option_c, option_d, correct_option, explanation, category)
       values ($1, $2, $3, $4, $5, $6, $7, $8, $9)
       on conflict (id) do update set
       question = excluded.question,
       option_a = excluded.option_a,
       option_b = excluded.option_b,
       option_c = excluded.option_c,
       option_d = excluded.option_d,
       correct_option = excluded.correct_option,
       explanation = excluded.explanation,
       category = excluded.category`,
      [row.id, row.question, row.option_a, row.option_b, row.option_c, row.option_d, row.correct_option, row.explanation, row.category]
    );
  }

  await pool.end();
};

main().catch(async (error) => {
  console.error(error);
  await pool.end();
  process.exit(1);
});
"}

{"filePath": "/app/public/styles.css", "content": ":root {
  color-scheme: dark;
  --bg: #111827;
  --panel: rgba(255, 255, 255, 0.1);
  --panel-strong: rgba(255, 255, 255, 0.16);
  --text: #f8fafc;
  --muted: #cbd5e1;
  --primary: #8b5cf6;
  --primary-2: #06b6d4;
  --good: #22c55e;
  --bad: #fb7185;
  --warn: #fbbf24;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--text);
  background:
    radial-gradient(circle at 20% 10%, rgba(139, 92, 246, 0.45), transparent 32rem),
    radial-gradient(circle at 80% 0%, rgba(6, 182, 212, 0.35), transparent 28rem),
    linear-gradient(135deg, #0f172a, var(--bg));
}

button {
  border: 0;
  border-radius: 999px;
  padding: 0.85rem 1.1rem;
  color: white;
  font-weight: 800;
  cursor: pointer;
  background: linear-gradient(135deg, var(--primary), var(--primary-2));
  box-shadow: 0 16px 34px rgba(6, 182, 212, 0.16);
  transition: transform 0.2s ease, opacity 0.2s ease, background 0.2s ease;
}

button:hover:not(:disabled) { transform: translateY(-2px); }
button:disabled { cursor: not-allowed; opacity: 0.55; }

.shell {
  width: min(980px, calc(100% - 2rem));
  margin: 0 auto;
  padding: 3rem 0;
}

.hero { text-align: center; margin-bottom: 2rem; }
.hero h1 { margin: 0; font-size: clamp(2.7rem, 8vw, 5.7rem); letter-spacing: -0.08em; }
.hero p { color: var(--muted); font-size: 1.1rem; }
.eyebrow { text-transform: uppercase; letter-spacing: 0.22em; font-weight: 900; color: #67e8f9 !important; }

.panel {
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 2rem;
  padding: clamp(1rem, 4vw, 2rem);
  background: var(--panel);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(18px);
}

.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 1rem; }
.card {
  text-align: left;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 1.25rem;
  padding: 1.1rem;
  background: var(--panel-strong);
}
.card strong { display: block; font-size: 1.1rem; margin-bottom: 0.35rem; }
.card span, .muted { color: var(--muted); }
.warning {
  border: 1px solid rgba(251, 191, 36, 0.5);
  background: rgba(251, 191, 36, 0.12);
  border-radius: 1rem;
  padding: 1rem;
  margin: 1rem 0;
  color: #fde68a;
}
.progress-bar { height: 0.75rem; background: rgba(255, 255, 255, 0.12); border-radius: 999px; overflow: hidden; }
.progress-fill { height: 100%; background: linear-gradient(90deg, var(--primary), var(--primary-2)); border-radius: inherit; }
.options { display: grid; gap: 0.8rem; margin: 1.4rem 0; }
.option { width: 100%; text-align: left; background: rgba(255, 255, 255, 0.12); box-shadow: none; }
.option.selected { outline: 3px solid #67e8f9; }
.option.correct { background: linear-gradient(135deg, #16a34a, #22c55e); }
.option.incorrect { background: linear-gradient(135deg, #e11d48, #fb7185); }
.feedback { border-radius: 1rem; padding: 1rem; margin: 1rem 0; background: rgba(255, 255, 255, 0.12); }
.feedback.correct { border: 1px solid var(--good); }
.feedback.incorrect { border: 1px solid var(--bad); }
.actions { display: flex; gap: 0.8rem; flex-wrap: wrap; align-items: center; margin-top: 1rem; }
.score { font-size: clamp(2rem, 8vw, 4rem); margin: 0.5rem 0; letter-spacing: -0.06em; }
.achievements { display: flex; flex-wrap: wrap; gap: 0.8rem; margin: 1rem 0; }
.badge { border-radius: 999px; padding: 0.7rem 1rem; background: rgba(139, 92, 246, 0.25); border: 1px solid rgba(167, 139, 250, 0.55); }
"}

{"filePath": "/app/public/app.js", "content": "const app = document.querySelector('#app');

const state = {
  categories: [],
  category: '',
  questions: [],
  index: 0,
  selected: '',
  answered: false,
  correct: 0,
  streak: 0,
  maxStreak: 0,
  startedAt: 0,
  surprise: false,
  warning: false
};

const optionLabels = ['A', 'B', 'C', 'D'];
const optionKeys = { A: 'option_a', B: 'option_b', C: 'option_c', D: 'option_d' };

const escapeHtml = (value) => String(value).replace(/[&<>"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[char]);

const render = (html) => {
  app.innerHTML = html;
};

const loadCategories = async () => {
  const response = await fetch('/api/categories');
  state.categories = await response.json();
  showCategories();
};

const showCategories = () => {
  const cards = [...state.categories.map((item) => ({ category: item.category, count: item.count })), { category: 'Surprise Me!', count: 'Random' }];
  render(`
    <h2 data-testid="text-category-heading">Choose your category</h2>
    <p class="muted" data-testid="text-category-description">All categories are available. Geography and Science have enough questions for every accomplishment.</p>
    <div class="grid">
      ${cards.map((item) => `
        <button class="card" data-testid="button-category-${escapeHtml(item.category)}" data-category="${escapeHtml(item.category)}">
          <strong data-testid="text-category-name-${escapeHtml(item.category)}">${escapeHtml(item.category)}</strong>
          <span data-testid="text-category-count-${escapeHtml(item.category)}">${escapeHtml(item.count)} ${Number.isInteger(item.count) ? 'questions' : 'category'}</span>
        </button>
      `).join('')}
    </div>
  `);
  app.querySelectorAll('[data-category]').forEach((button) => button.addEventListener('click', () => startQuiz(button.dataset.category)));
};

const startQuiz = async (category, force = false) => {
  const response = await fetch(`/api/quiz?category=${encodeURIComponent(category)}`);
  const data = await response.json();
  state.category = data.category;
  state.questions = data.questions;
  state.surprise = data.surprise;
  state.warning = data.warning;
  state.index = 0;
  state.selected = '';
  state.answered = false;
  state.correct = 0;
  state.streak = 0;
  state.maxStreak = 0;
  state.startedAt = Date.now();

  if (state.warning && !force) return showWarning();
  showQuestion();
};

const showWarning = () => {
  render(`
    <h2 data-testid="text-warning-heading">${state.surprise ? `Surprise category: ${escapeHtml(state.category)}` : escapeHtml(state.category)}</h2>
    <div class="warning" data-testid="status-question-warning">Not enough questions in this category for all accomplishments</div>
    <p data-testid="text-warning-count">This round has ${state.questions.length} questions.</p>
    <div class="actions">
      <button data-testid="button-proceed-warning" id="proceed">Proceed Anyway</button>
      <button data-testid="button-new-category" id="newCategory">New Category</button>
    </div>
  `);
  app.querySelector('#proceed').addEventListener('click', showQuestion);
  app.querySelector('#newCategory').addEventListener('click', showCategories);
};

const showQuestion = () => {
  const question = state.questions[state.index];
  const progress = Math.round((state.index / state.questions.length) * 100);
  render(`
    <p class="eyebrow" data-testid="text-active-category">${state.surprise && state.index === 0 ? 'Surprise category: ' : ''}${escapeHtml(state.category)}</p>
    <h2 data-testid="text-question">${escapeHtml(question.question)}</h2>
    <p data-testid="text-progress">Question ${state.index + 1} of ${state.questions.length}</p>
    <div class="progress-bar" data-testid="status-progress-bar"><div class="progress-fill" data-testid="status-progress-fill" style="width: ${progress}%"></div></div>
    <div class="options">
      ${optionLabels.map((label) => `<button class="option" data-testid="button-answer-${label}" data-option="${label}">${label}. ${escapeHtml(question[optionKeys[label]])}</button>`).join('')}
    </div>
    <button data-testid="button-submit-answer" id="submit" disabled>Submit Answer</button>
  `);
  app.querySelectorAll('[data-option]').forEach((button) => button.addEventListener('click', () => selectOption(button.dataset.option)));
  app.querySelector('#submit').addEventListener('click', submitAnswer);
};

const selectOption = (option) => {
  state.selected = option;
  app.querySelectorAll('[data-option]').forEach((button) => button.classList.toggle('selected', button.dataset.option === option));
  app.querySelector('#submit').disabled = false;
};

const submitAnswer = () => {
  const question = state.questions[state.index];
  const isCorrect = state.selected === question.correct_option;
  state.answered = true;
  if (isCorrect) {
    state.correct += 1;
    state.streak += 1;
  } else {
    state.streak = 0;
  }
  state.maxStreak = Math.max(state.maxStreak, state.streak);

  app.querySelectorAll('[data-option]').forEach((button) => {
    button.disabled = true;
    button.classList.toggle('correct', button.dataset.option === question.correct_option);
    button.classList.toggle('incorrect', button.dataset.option === state.selected && !isCorrect);
  });
  app.querySelector('#submit').remove();
  app.insertAdjacentHTML('beforeend', `
    <div class="feedback ${isCorrect ? 'correct' : 'incorrect'}" data-testid="status-answer-feedback">
      <strong data-testid="text-answer-result">${isCorrect ? 'Correct!' : 'Incorrect'}</strong>
      <p data-testid="text-answer-explanation">${escapeHtml(question.explanation)}</p>
    </div>
    <button data-testid="button-next-question" id="next">${state.index === state.questions.length - 1 ? 'See Results' : 'Next Question'}</button>
  `);
  app.querySelector('#next').addEventListener('click', nextStep);
};

const nextStep = () => {
  if (state.index === state.questions.length - 1) return showResults();
  state.index += 1;
  state.selected = '';
  state.answered = false;
  showQuestion();
};

const showResults = () => {
  const elapsed = Math.max(1, Math.round((Date.now() - state.startedAt) / 1000));
  const percent = Math.round((state.correct / state.questions.length) * 100);
  const achievements = [];
  if (state.questions.length === 10 && state.correct === state.questions.length) achievements.push('Perfect Round');
  if (state.maxStreak >= 5) achievements.push('Hot Streak');
  if (state.maxStreak >= 3) achievements.push('Triple Win');

  render(`
    <h2 data-testid="text-results-heading">Round Results</h2>
    <p class="score" data-testid="text-score">${state.correct}/${state.questions.length} Correct (${percent}%)</p>
    <p data-testid="text-elapsed-time">Elapsed time: ${elapsed} seconds</p>
    <p data-testid="text-max-streak">Best streak: ${state.maxStreak}</p>
    <h3 data-testid="text-achievements-heading">Achievements</h3>
    ${achievements.length ? `<div class="achievements">${achievements.map((name) => `<span class="badge" data-testid="text-achievement-${escapeHtml(name)}">${escapeHtml(name)}</span>`).join('')}</div>` : '<p data-testid="text-no-achievements">No achievements this round</p>'}
    <div class="actions">
      <button data-testid="button-play-again" id="again">Play Again</button>
      <button data-testid="button-new-category" id="newCategory">New Category</button>
    </div>
  `);
  app.querySelector('#again').addEventListener('click', () => startQuiz(state.category, true));
  app.querySelector('#newCategory').addEventListener('click', showCategories);
};

loadCategories().catch((error) => {
  render(`<p data-testid="status-error">${escapeHtml(error.message)}</p>`);
});
"}

